fn three_binding_inputs(
    memory: &mut Memory,
) -> (
    ValidatedKernelEnvelope<'static>,
    [Gfx942FixedDispatchPacketV1; 1],
    Vec<Gfx942FixedDispatchDataV1>,
) {
    use fe2o3_amdhsa_loader::{AdmittedProfile, KernelGlobalBufferAbiV1, validate};
    let image =
