            Self::UserptrProbe => 3,
        }
    }

    const fn gpu_va_bytes(self, logical_bytes: u32) -> u64 {
        match self {
            Self::AqlSpecial | Self::ExecutableProbe | Self::UserptrProbe => logical_bytes as u64,
        }
    }
}

enum CpuRingAuthorityV1 {
