            .map_err(NativeBarrierAndSubmissionFailureV1::Terminal)?;
        let engine = self
            .engine
            .as_mut()
            .ok_or(NativeAqlSubmissionErrorV1::InvalidQueue(
                "missing queue engine",
            ))
            .map_err(NativeBarrierAndSubmissionFailureV1::Terminal)?;
        if engine.phase(self.key) != Some(ComputeAqlQueuePhaseV1::Active) {
